package com.bank.courier;

import java.util.logging.Logger;

public class RoutePlanner {

    private static final Logger log = Logger.getLogger(RoutePlanner.class.getName());

    public int uniquePaths(int m, int n) {
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) dp[i][0] = 1;      // left edge: one way (all down)
        for (int j = 0; j < n; j++) dp[0][j] = 1;      // top edge: one way (all right)
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]; // from above + from left
            }
        }
        int result = dp[m - 1][n - 1];
        log.info(() -> "uniquePaths(" + m + "," + n + ") = " + result);
        return result;
    }
}
