package com.bank.courier;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class UniquePathsDemo {

    private static final Logger log = Logger.getLogger(UniquePathsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Courier Route Planner (Unique Paths)");
        RoutePlanner planner = new RoutePlanner();
        log.info("3x7 grid → " + planner.uniquePaths(3, 7)); // 28
        log.info("3x2 grid → " + planner.uniquePaths(3, 2)); // 3
    }
}
